// Minimal endless runner for canvas with id "game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.offsetWidth || 800;
  const H = canvas.height = canvas.offsetHeight || 200;

  // player definition
  const player = {
    x: 50,
    y: H - 30,
    w: 20,
    h: 30,
    vy: 0,
    jumpStrength: -8,
    gravity: 0.4,
    onGround: true,
    sliding: false,
    slideHeight: 15,
  };

  const obstacles = [];
  let speed = 2;
  let frame = 0;
  let score = 0;
  let gameOver = false;

  // Input handling
  const onJump = () => {
    if (player.onGround && !player.sliding) {
      player.vy = player.jumpStrength;
      player.onGround = false;
    }
  };
  const onSlide = (down) => {
    if (down && player.onGround && !player.sliding) {
      player.sliding = true;
      player.h = player.slideHeight;
      player.y = H - player.h;
    } else if (!down && player.sliding) {
      player.sliding = false;
      player.h = 30;
      player.y = H - player.h;
    }
  };
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'ArrowUp') onJump();
    if (e.code === 'ArrowDown') onSlide(true);
  });
  document.addEventListener('keyup', (e) => {
    if (e.code === 'ArrowDown') onSlide(false);
  });
  canvas.addEventListener('click', onJump);

  // obstacle generator
  function addObstacle() {
    const type = Math.random() < 0.5 ? 'spike' : 'gap';
    const w = 20 + Math.random() * 30;
    const h = type === 'spike' ? 20 + Math.random() * 20 : 0; // gap handled by y=H
    const ob = {
      x: W,
      y: H - h,
      w,
      h,
      type,
    };
    obstacles.push(ob);
  }

  function update() {
    if (gameOver) return;

    // player physics
    player.vy += player.gravity;
    player.y += player.vy;
    if (player.y + player.h >= H) {
      player.y = H - player.h;
      player.vy = 0;
      player.onGround = true;
    }

    // obstacles movement
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      // remove off-screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    // spawn
    if (frame % 100 === 0) addObstacle();

    // collision detection (AABB)
    for (const o of obstacles) {
      if (o.type === 'gap') continue; // gap handled by falling
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        gameOver = true;
      }
    }
    // gap check (if player is over a gap area)
    for (const o of obstacles) {
      if (o.type !== 'gap') continue;
      if (player.x + player.w > o.x && player.x < o.x + o.w) {
        // player is over gap
        if (player.y + player.h >= H) {
          gameOver = true;
        }
      }
    }

    score++;
    frame++;
    if (frame % 500 === 0) speed += 0.5; // gradual speed increase
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    // ground line
    ctx.fillStyle = '#654321';
    ctx.fillRect(0, H - 5, W, 5);

    // player
    ctx.fillStyle = '#00f';
    ctx.fillRect(player.x, player.y, player.w, player.h);

    // obstacles
    ctx.fillStyle = '#f00';
    for (const o of obstacles) {
      if (o.type === 'gap') continue;
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }

    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score / 60), 10, 20);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W / 2 - 60, H / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  loop();
})();
